    internal sealed record Projection(float Along, float Distance, Vector3 Point);

    // A lockout transfer can put C in physical A. Keep that departure corridor until
    // the authored routes meet at X285/Z280. Recomputing nearest pads while crossing
    // toward the merge, or switching at X270, selected an unreachable chord on Oct 7.
    internal sealed class DepartureLane
    {
        private int occupied=-1;
        internal void Reset()=>occupied=-1;
        internal int Resolve(int phase,Vector3 player,int assigned)
        {
            if(phase!=3||player.X<=190||player.X>=285){Reset();return assigned;}
            if(occupied<0)occupied=LabyrinthPlanner.Nearest(new(player.X,player.Z),LabyrinthPlanner.AtomosPads);
            return occupied;
        }
    }
    internal static Projection Project(Vector3 p, Vector3[] route)
    {
        float length=0;Projection best=null;
        for(int i=0;i<route.Length-1;i++)
        {
            var d=route[i+1]-route[i];float l=d.Length();
            float t=l<.01f?0:Math.Clamp(Vector3.Dot(p-route[i],d)/(l*l),0,1);
            var q=route[i]+d*t;float distance=Vector3.Distance(p,q);
            if(best==null||distance<best.Distance)best=new(length+t*l,distance,q);
            length+=l;
        }
        return best;
    }
    internal static Vector3 At(Vector3[] route,float along)
    {
        for(int i=0;i<route.Length-1;i++)
        {float length=Vector3.Distance(route[i],route[i+1]);if(length<.01f)continue;if(along<=length)return Vector3.Lerp(route[i],route[i+1],Math.Clamp(along/length,0,1));along-=length;}
        return route.Last();
    }

    internal static Vector3? Tether(Vector3 player,Vector3[] party,Vector3[] route,bool lead)
    {
        var me=Project(player,route);
        var progress=party.Select(p=>Project(p,route)).Where(p=>p.Distance<22).Select(p=>p.Along).Order().ToArray();
        if(progress.Length<3)return null;
        // A median defeats a lone sprinter. Tanks get ten yalms of lead; everyone else trails
        // the middle of the party. This also prevents a normal MoveTo from racing to the boss.
        float frontier=progress[progress.Length/2]+(lead?10:1);
        if(frontier<=me.Along+1)return null;
        return At(route,Math.Min(frontier,me.Along+8));
    }

    // Allies beyond a one-way transition authorize catching up, not skipping the approach.
    // The October 7 hub fallback targeted a trigger 247 yalms away and pushed into a wall.
    internal static Vector3 ApproachStep(Vector3 player,Vector3[] route) =>
        At(route,Project(player,route).Along+8);
